-- Import the PDF supplied for the Motorcycle Catalog task (1995-2026).
-- CC is kept in its own column; cc_category is generated by the preceding
-- migration, so its Small Bike / Large Bike boundary cannot drift from CC.
-- Four source models have distinct CC versions. Their displayed model label
-- includes CC so the existing brand+model booking identity remains unambiguous.
-- The sole electric entry has no combustion CC. It is retained for catalog
-- completeness, but inactive because it has no requested CC price category.

CREATE TEMP TABLE _motorcycle_catalog_source (
  brand text NOT NULL,
  model text NOT NULL,
  legacy_model text NOT NULL,
  engine_cc numeric(6, 1),
  legacy_preference integer NOT NULL,
  is_active boolean NOT NULL
) ON COMMIT DROP;

