-- Convert prior catalog labels such as "Honda ADV160" to the PDF's single
-- canonical entry before upserting. Appointment snapshots are updated in the
-- same migration, so reschedules and admin edits still resolve their catalog row.
CREATE TEMP TABLE _motorcycle_catalog_legacy_mapping ON COMMIT DROP AS
WITH candidates AS (
  SELECT
    catalog.id,
    catalog.brand AS old_brand,
    catalog.model AS old_model,
    source.brand AS new_brand,
    source.model AS new_model,
    source.engine_cc AS new_engine_cc,
    source.is_active AS new_is_active,
    row_number() OVER (
      PARTITION BY catalog.id
      ORDER BY source.legacy_preference, source.engine_cc NULLS LAST, source.model
    ) AS candidate_rank
  FROM public.motorcycle_catalog AS catalog
  JOIN _motorcycle_catalog_source AS source
    ON regexp_replace(lower(btrim(catalog.brand)), '[^a-z0-9]+', '', 'g')
       = regexp_replace(lower(btrim(source.brand)), '[^a-z0-9]+', '', 'g')
   AND (
     regexp_replace(lower(btrim(catalog.model)), '[^a-z0-9]+', '', 'g')
       = regexp_replace(lower(btrim(source.model)), '[^a-z0-9]+', '', 'g')
     OR regexp_replace(lower(btrim(catalog.model)), '[^a-z0-9]+', '', 'g')
       = regexp_replace(lower(btrim(source.legacy_model)), '[^a-z0-9]+', '', 'g')
     OR regexp_replace(lower(btrim(catalog.model)), '[^a-z0-9]+', '', 'g')
       = regexp_replace(lower(btrim(source.brand || source.legacy_model)), '[^a-z0-9]+', '', 'g')
   )
)
SELECT
  id, old_brand, old_model, new_brand, new_model, new_engine_cc, new_is_active
FROM candidates
WHERE candidate_rank = 1;

UPDATE public.appointments AS appointment
SET
  moto_brand = mapping.new_brand,
  moto_model = mapping.new_model
FROM _motorcycle_catalog_legacy_mapping AS mapping
WHERE lower(btrim(appointment.moto_brand)) = lower(btrim(mapping.old_brand))
  AND lower(btrim(appointment.moto_model)) = lower(btrim(mapping.old_model));

UPDATE public.motorcycle_catalog AS catalog
SET
  brand = mapping.new_brand,
  model = mapping.new_model,
  engine_cc = mapping.new_engine_cc,
  is_active = mapping.new_is_active,
  is_archived = false,
  archived_at = NULL
FROM _motorcycle_catalog_legacy_mapping AS mapping
WHERE catalog.id = mapping.id
  AND NOT EXISTS (
    SELECT 1
    FROM public.motorcycle_catalog AS existing
    WHERE existing.id <> catalog.id
      AND existing.brand = mapping.new_brand
      AND existing.model = mapping.new_model
  );

INSERT INTO public.motorcycle_catalog (
  brand, model, engine_cc, is_active, is_archived, archived_at
)
SELECT brand, model, engine_cc, is_active, false, NULL
FROM _motorcycle_catalog_source
ON CONFLICT (brand, model) DO UPDATE
SET
  engine_cc = EXCLUDED.engine_cc,
  is_active = EXCLUDED.is_active,
  is_archived = false,
  archived_at = NULL;

-- A customer-facing catalog item must be classifiable for service pricing.
-- This also keeps a future direct database write from exposing an item that
-- availability and booking would correctly reject.
UPDATE public.motorcycle_catalog
SET is_active = false
WHERE is_active = true
  AND engine_cc IS NULL;

ALTER TABLE public.motorcycle_catalog
  DROP CONSTRAINT IF EXISTS motorcycle_catalog_active_requires_engine_cc;

ALTER TABLE public.motorcycle_catalog
  ADD CONSTRAINT motorcycle_catalog_active_requires_engine_cc
  CHECK (NOT is_active OR engine_cc IS NOT NULL);

COMMENT ON COLUMN public.motorcycle_catalog.cc_category IS
  'Derived from engine_cc: small_bike for 125cc and below; Large Bike above 125cc.';

NOTIFY pgrst, 'reload schema';
